Lemma bytes_at_sub : forall m A (bs : list byte) i k, bytes_at asegs m A bs -> (i + k <= length bs)%nat ->
  bytes_at asegs m (A + Z.of_nat i) (firstn k (skipn i bs)).
Proof.
